/* SD Akademie – JavaScript Aufbau P4. */
(function(root){"use strict";root.SDAkademieKurse=root.SDAkademieKurse||Object.create(null);root.SDAkademieKurse["javascript-aufbau"]=[{"id":"p4-1","title":"Arrays mit map umformen","minutes":30,"ziel":"Aus einer Preisliste neue Werte erzeugen","schritte":[{"titel":"Ausgangsliste vorbereiten","text":"Eine Preisliste ist wie eine Reihe von Etiketten im Laden. `const preise = [4, 7, 10];` legt drei Zahlen in einer festen Reihenfolge ab. Die eckigen Klammern erzeugen das Array. Jede Zahl steht für einen Preis vor der Umrechnung. Kontrolliere zuerst mit `console.log(preise)`, welche Werte wirklich enthalten sind.","code":"const preise = [4, 7, 10]; const brutto = preise.map(preis => preis * 1.19); console.log(brutto);","erklaerung":"Ein einzelner Preis wird mit dem Faktor 1.19 multipliziert; dadurch entstehen umgerechnete Zahlen.","tiefer":["`map`, `filter` und `reduce` sind Methoden höherer Ordnung: Sie bekommen eine Funktion als Argument und wenden sie auf die Einträge an. Diese Arbeitsweise stammt aus der funktionalen Programmierung. Statt zu beschreiben, wie eine Schleife zählt, beschreibst du nur, was mit jedem Eintrag passieren soll.","Eine solche Ausgangsliste sollte möglichst gleichartige Werte enthalten, hier nur Zahlen. Dann kann dieselbe Regel auf jeden Eintrag angewendet werden, ohne Sonderfälle. Gemischte Listen aus Texten und Zahlen führen bei Berechnungen schnell zu `NaN`."]},{"titel":"Mit map jeden Preis bearbeiten","text":"An einer Kasse wird auf jedes Etikett dieselbe Regel angewendet. `preise.map(preis => preis * 1.19)` ruft die Pfeilfunktion für jeden Eintrag auf. Links vom Pfeil steht der aktuelle Preis. Rechts davon steht die Rechnung für den neuen Wert. map liefert ein neues Array und verändert die ursprüngliche Preisliste nicht.","code":"const preise = [4, 7, 10]; const brutto = preise.map(preis => preis * 1.19); console.log(brutto);","erklaerung":"Die Pfeilfunktion liefert für jeden Eintrag einen Wert und baut daraus eine zweite Liste.","tiefer":["`map` ruft die übergebene Funktion für jeden Eintrag auf und sammelt die Rückgabewerte in einem neuen Array derselben Länge. Die Funktion bekommt zusätzlich den Index und das ganze Array: `preise.map((preis, i) => ...)`. Meist braucht man nur den ersten Parameter.","Bei einer Pfeilfunktion mit nur einem Ausdruck wird dieser automatisch zurückgegeben. Schreibst du geschweifte Klammern, brauchst du ein ausdrückliches `return`, sonst entsteht ein Array voller `undefined`. Das ist einer der häufigsten Fehler bei `map`."]},{"titel":"Das Ergebnis speichern","text":"Ein zweiter Zettel kann die umgerechneten Preise enthalten, während der erste erhalten bleibt. `const brutto = preise.map(preis => preis * 1.19);` speichert die neue Liste. Das Wort brutto ist hier nur ein Variablenname. `console.log(brutto)` zeigt drei berechnete Zahlen. Vergleiche anschließend die unveränderte Variable preise mit dem Ergebnis.","code":"const preise = [4, 7, 10]; const brutto = preise.map(preis => preis * 1.19); console.log(brutto);","erklaerung":"Die neue Variable brutto hält das Ergebnis getrennt von der ursprünglichen Einkaufsliste.","tiefer":["`map` verändert das Original nicht. Diese Unveränderlichkeit macht Programme leichter nachvollziehbar: Wer `preise` liest, sieht immer die Nettopreise. Frameworks wie React erkennen Änderungen genau daran, dass ein neues Array entsteht.","Da jede dieser Methoden wieder ein Array liefert, kann man sie verketten: `preise.map(...).filter(...)`. Jeder Schritt ist für sich verständlich. Bei sehr großen Listen erzeugt jede Stufe allerdings ein Zwischenarray; für Lernzwecke und normale Datenmengen spielt das keine Rolle."]},{"titel":"Nachkommastellen beachten","text":"Auf Preisschildern sind zwei Nachkommastellen üblich, bei Berechnungen können mehr entstehen. `brutto.map(wert => wert.toFixed(2))` formatiert jeden Wert mit zwei Stellen. Die Methode toFixed liefert allerdings Strings zurück. Für weitere Rechnungen solltest du die Zahlenwerte behalten. Trenne daher Berechnung und Anzeige bewusst voneinander.","code":"const preise = [4, 7, 10]; const brutto = preise.map(preis => preis * 1.19); console.log(brutto);","erklaerung":"Mit toFixed werden Beträge für die Anzeige formatiert, nicht für weitere Rechenschritte.","tiefer":["`toFixed(2)` rundet und liefert einen String, etwa `'4.76'`. Rechnest du danach weiter, wandle ihn mit `Number()` zurück. Am besten formatierst du erst ganz am Ende für die Anzeige und rechnest bis dahin mit Zahlen.","Für deutsche Preisangaben mit Komma und Euro-Zeichen gibt es `new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(wert)`. Das Ergebnis lautet dann zum Beispiel „4,76 €“. Für genaue Geldrechnungen rechnen viele Programme intern in Cent als ganzen Zahlen."]}],"beispiel":{"html":"<h1>Preise umrechnen</h1><p id='ausgabe'>Öffne die Konsole.</p>","css":"","js":""},"aufgabe":{"text":"Baue das Beispiel „Arrays mit map umformen“ nach. Prüfe die Konsole und ändere einen Beispielwert.","tipp":"Prüfe mit einer Liste aus drei Preisen, ob map dieselbe Anzahl von Ergebnissen liefert.","pruefungen":[{"beschreibung":"Die Übungsoberfläche ist vorhanden.","test":"p4-1-html"},{"beschreibung":"Die JavaScript-Technik wurde eingesetzt.","test":"p4-1-js"}],"loesung":{"html":"<h1>Preise umrechnen</h1><p id='ausgabe'>Öffne die Konsole.</p>","css":"","js":"const preise = [4, 7, 10]; const brutto = preise.map(preis => preis * 1.19); console.log(brutto);"}},"fehler":[{"titel":"map auf einer Zahl","text":"Falsch: `const preise = 5; preise.map(x => x * 2);` erzeugt `TypeError: preise.map is not a function`, weil 5 kein Array ist. Richtig: `const preise = [5]; preise.map(x => x * 2);` liefert `[10]`."},{"titel":"Ursprungsliste mit Ergebnis verwechselt","text":"Falsch: `preise.map(x => x * 2); console.log(preise);` zeigt weiterhin `[4,7,10]`, nicht die verdoppelten Werte. Richtig: `const neu = preise.map(x => x * 2); console.log(neu);` zeigt `[8,14,20]`."}],"quiz":[{"frage":"Was liefert map?","antworten":["Eine neue Liste","Immer eine einzelne Zahl","Nur true"],"richtig":0,"erklaerung":"Richtig ist „Eine neue Liste“. Das folgt aus dem konkreten Verhalten von arrays mit map umformen, das in Schritt 1 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]},{"frage":"Was bedeutet preis links vom Pfeil?","antworten":["Eine CSS-Klasse","Der Dateiname","Der aktuelle Eintrag"],"richtig":2,"erklaerung":"Richtig ist „Der aktuelle Eintrag“. Das folgt aus dem konkreten Verhalten von arrays mit map umformen, das in Schritt 2 erläutert wird.","begruendungen":["Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Was bleibt bei map erhalten?","antworten":["Nur der erste Wert","Das ursprüngliche Array","Nur der letzte Wert"],"richtig":1,"erklaerung":"Richtig ist „Das ursprüngliche Array“. Das folgt aus dem konkreten Verhalten von arrays mit map umformen, das in Schritt 3 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]}],"merke":["map erzeugt neue Einträge und behält die ursprüngliche Liste unverändert.","Berechnung und Formatierung von Preisen sind unterschiedliche Aufgaben."],"explanation":"Mit Array-Methoden kannst du ganze Datenlisten lesbar verarbeiten. In diesem Modul übst du das Umformen von Werten ohne unnötige Schleifen."},{"id":"p4-2","title":"Mit filter passende Einträge finden","minutes":30,"ziel":"Eine Liste nach einer Bedingung durchsuchen","schritte":[{"titel":"Eine Liste mit Zahlen lesen","text":"Bei einer Veranstaltung werden Altersangaben in einer Liste gesammelt. `const alter = [15, 22, 17, 31];` speichert vier Zahlen. Jeder Eintrag kann einzeln geprüft werden. Zunächst bleiben alle Angaben unverändert. Gib die Liste aus, damit du die Ausgangslage kennst.","code":"const alter = [15, 22, 17, 31]; const erwachsene = alter.filter(wert => wert >= 18); console.log(erwachsene);","erklaerung":"Das Array enthält vier Altersangaben, die zuerst vollständig angezeigt werden.","tiefer":["Bevor du filterst, lohnt ein Blick auf die Daten: Sind alle Einträge Zahlen? Gibt es leere oder unmögliche Werte? Daten aus Formularen kommen oft als Text an und müssen zuerst mit `Number()` umgewandelt werden, sonst vergleicht JavaScript womöglich Texte.","Datenschutz beginnt schon hier: Altersangaben sind personenbezogene Daten. Sammle nur, was du wirklich brauchst, und speichere sie nicht länger als nötig. In Übungen verwendest du ausgedachte Beispielwerte."]},{"titel":"Eine Bedingung formulieren","text":"Am Eingang gilt eine klare Regel: mindestens 18 Jahre. `wert >= 18` ergibt für jeden Eintrag true oder false. Das Zeichen >= bedeutet größer oder gleich. Für 18 ist die Bedingung bereits erfüllt. Für 17 ist sie falsch.","code":"const alter = [15, 22, 17, 31]; const erwachsene = alter.filter(wert => wert >= 18); console.log(erwachsene);","erklaerung":"Der Vergleich >= schließt die Grenze von 18 ausdrücklich ein.","tiefer":["Eine Funktion, die für einen Eintrag `true` oder `false` liefert, heißt Prädikat. Du kannst sie auch benennen und wiederverwenden: `const istErwachsen = wert => wert >= 18;` und dann `alter.filter(istErwachsen)`. Das macht den Code lesbarer.","Mehrere Bedingungen verbindest du mit `&&` (und) und `||` (oder): `wert >= 18 && wert < 65`. Achte bei Grenzen genau auf `>` und `>=`. Die Grenze 18 selbst gehört bei „mindestens 18“ dazu."]},{"titel":"Mit filter auswählen","text":"Ein Türsteher lässt nur Personen durch, die die Regel erfüllen. `alter.filter(wert => wert >= 18)` behält die passenden Zahlen. Die Funktion wird für jeden Eintrag ausgeführt. Ein wahrer Rückgabewert übernimmt den Eintrag in die neue Liste. Das Ergebnis enthält hier 22 und 31.","code":"const alter = [15, 22, 17, 31]; const erwachsene = alter.filter(wert => wert >= 18); console.log(erwachsene);","erklaerung":"Die Filterfunktion übernimmt ausschließlich Werte mit wahrem Vergleichsergebnis.","tiefer":["`filter` liefert immer ein neues Array, auch wenn kein Eintrag passt – dann eben ein leeres. Brauchst du nur den ersten passenden Eintrag, nimm `find`; es liefert den Wert selbst oder `undefined`. `some` beantwortet, ob mindestens einer passt, `every`, ob alle passen.","Der Rückgabewert der Funktion wird als Wahrheitswert gedeutet. Liefert sie versehentlich etwas anderes, etwa durch fehlendes `return` in geschweiften Klammern, ist das Ergebnis leer. Mit `console.log` innerhalb der Funktion siehst du, für welche Werte sie was liefert."]},{"titel":"Ergebnis und Ursprung vergleichen","text":"Eine Gästeliste wird gefiltert, ohne dass die ursprünglichen Anmeldungen verschwinden. `const erwachsene = alter.filter(wert => wert >= 18);` speichert die Auswahl. `console.log(alter.length)` liefert weiterhin vier. `console.log(erwachsene.length)` liefert zwei. Ändere den Grenzwert und beobachte die neue Anzahl.","code":"const alter = [15, 22, 17, 31]; const erwachsene = alter.filter(wert => wert >= 18); console.log(erwachsene);","erklaerung":"Die Anzahl der ursprünglichen Anmeldungen bleibt trotz Auswahl gleich.","tiefer":["Original und Auswahl nebeneinander zu haben ist praktisch: Man kann jederzeit anders filtern, ohne die Daten neu laden zu müssen. Viele Suchfunktionen auf Webseiten arbeiten genau so – bei jeder Eingabe wird aus der vollständigen Liste neu gefiltert.","Häufig folgen `filter` und `map` aufeinander: zuerst die passenden Einträge auswählen, dann umformen. Zum Beispiel `personen.filter(p => p.alter >= 18).map(p => p.name)` liefert die Namen aller Erwachsenen."]}],"beispiel":{"html":"<h1>Teilnehmende auswählen</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Baue das Beispiel „Mit filter passende Einträge finden“ nach. Prüfe die Konsole und ändere einen Beispielwert.","tipp":"Teste das Ereignis zunächst mit einem einzigen Knopf und kontrolliere die Reaktion in der Konsole.","pruefungen":[{"beschreibung":"Die Übungsoberfläche ist vorhanden.","test":"p4-2-html"},{"beschreibung":"Die JavaScript-Technik wurde eingesetzt.","test":"p4-2-js"}],"loesung":{"html":"<h1>Teilnehmende auswählen</h1><p id='ausgabe'></p>","css":"","js":"const alter = [15, 22, 17, 31]; const erwachsene = alter.filter(wert => wert >= 18); console.log(erwachsene);"}},"fehler":[{"titel":"filter mit einer Zahl statt Bedingung","text":"Falsch: `alter.filter(wert => 18);` behält alle Einträge, weil die Zahl 18 als wahr gilt. In der Konsole bleibt die gesamte Liste sichtbar. Richtig: `alter.filter(wert => wert >= 18);` behält nur passende Werte."},{"titel":"filter verändert das Ursprungsarray nicht","text":"Falsch: `alter.filter(x => x >= 18); console.log(alter);` zeigt noch vier Werte, obwohl du zwei erwartest. Richtig: `const auswahl = alter.filter(x => x >= 18); console.log(auswahl);` zeigt `[22,31]`."}],"quiz":[{"frage":"Welcher Wert wird bei >= 18 behalten?","antworten":["17","18","15"],"richtig":1,"erklaerung":"Richtig ist „18“. Das folgt aus dem konkreten Verhalten von mit filter passende einträge finden, das in Schritt 1 erläutert wird.","begruendungen":["Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Was erwartet filter von der Funktion?","antworten":["Eine wahre oder falsche Bedingung","Eine Farbe","Eine Datei"],"richtig":0,"erklaerung":"Richtig ist „Eine wahre oder falsche Bedingung“. Das folgt aus dem konkreten Verhalten von mit filter passende einträge finden, das in Schritt 2 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]},{"frage":"Was geschieht mit alter?","antworten":["Es wird gelöscht","Es wird ein String","Es bleibt unverändert"],"richtig":2,"erklaerung":"Richtig ist „Es bleibt unverändert“. Das folgt aus dem konkreten Verhalten von mit filter passende einträge finden, das in Schritt 3 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]}],"merke":["filter prüft jeden Eintrag auf eine Bedingung und behält nur Treffer.","Die Grenze >= 18 schließt Menschen mit genau 18 Jahren ein."],"explanation":"Eine Web-App muss auf Benutzereingaben reagieren und dabei verständlich bleiben. Du lernst, passende Ereignisse zu behandeln und Zustände sauber zu ändern."},{"id":"p4-3","title":"Mit reduce Werte zusammenfassen","minutes":30,"ziel":"Die Summe mehrerer Beträge berechnen","schritte":[{"titel":"Eine Rechnung vorbereiten","text":"Am Tagesende zählt eine kleine Kasse mehrere Einnahmen zusammen. `const betraege = [5, 8, 12];` speichert die Einzelbeträge. Du könntest sie einzeln addieren, aber bei langen Listen wird das unpraktisch. Eine wiederholte Addition passt besser. Prüfe vorab die Zahlen im Array.","code":"const betraege = [5, 8, 12]; const summe = betraege.reduce((gesamt, wert) => gesamt + wert, 0); console.log(summe);","erklaerung":"Die Kassenliste enthält drei Einnahmen, die addiert werden sollen.","tiefer":["`reduce` heißt „verringern“: Eine ganze Liste wird auf einen einzigen Wert zusammengefasst. Das kann eine Summe sein, aber auch ein Höchstwert, ein Objekt mit Zählungen oder sogar ein neues Array. Es ist die vielseitigste der drei Methoden.","Für eine einfache Summe ist auch eine Schleife völlig in Ordnung. `reduce` lohnt sich vor allem, wenn du den Ablauf in einer kompakten Kette mit `map` und `filter` schreiben willst. Lesbarkeit ist wichtiger als Kürze."]},{"titel":"Den Sammelwert verstehen","text":"Ein Taschenrechner merkt sich den bisherigen Zwischenstand. In `reduce((gesamt, wert) => gesamt + wert, 0)` übernimmt gesamt diese Rolle. wert ist jeweils der nächste Betrag. Die Funktion addiert beide Zahlen. Das Ergebnis wird der neue Zwischenstand.","code":"const betraege = [5, 8, 12]; const summe = betraege.reduce((gesamt, wert) => gesamt + wert, 0); console.log(summe);","erklaerung":"gesamt ist der bisherige Stand, wert die nächste Zahl aus dem Array.","tiefer":["Der erste Parameter heißt Akkumulator, weil er den Zwischenstand ansammelt. Was die Funktion zurückgibt, wird im nächsten Durchlauf zum neuen Akkumulator. Vergisst du das Zurückgeben, ist der Akkumulator ab dem zweiten Durchlauf `undefined`.","Schritt für Schritt bei `[5, 8, 12]`: Start 0, dann 0 + 5 = 5, dann 5 + 8 = 13, dann 13 + 12 = 25. Das Nachspielen auf Papier ist der beste Weg, reduce zu verstehen. Mit `console.log(gesamt, wert)` in der Funktion siehst du jeden Zwischenstand."]},{"titel":"Den Startwert festlegen","text":"Eine leere Kasse beginnt mit null Euro. Das letzte Argument `0` setzt den Anfangswert der Berechnung. Damit kann auch eine leere Liste sinnvoll zu null reduziert werden. Ohne Startwert wäre das Verhalten bei leeren Arrays problematisch. Verwende für Summen deshalb bewusst einen numerischen Startwert.","code":"const betraege = [5, 8, 12]; const summe = betraege.reduce((gesamt, wert) => gesamt + wert, 0); console.log(summe);","erklaerung":"Der numerische Startwert null verhindert Probleme mit leeren Listen.","tiefer":["Ohne Startwert nimmt `reduce` den ersten Eintrag als Startwert und beginnt beim zweiten. Bei einem leeren Array gibt es dann keinen Startwert, und JavaScript wirft einen TypeError. Mit Startwert ist das Verhalten immer klar.","Der Startwert bestimmt auch den Typ des Ergebnisses: `0` für Summen, `''` für zusammengesetzte Texte, `{}` für Zählungen. Beispiel: `woerter.reduce((z, w) => { z[w] = (z[w] ?? 0) + 1; return z; }, {})` zählt, wie oft jedes Wort vorkommt."]},{"titel":"Die Summe ausgeben","text":"Ein Kassenbon zeigt am Ende einen Gesamtbetrag. `const summe = betraege.reduce((gesamt, wert) => gesamt + wert, 0);` speichert ihn. `console.log(summe)` zeigt 25. Das ursprüngliche Array bleibt bestehen. Teste zusätzlich eine Liste mit nur einem Betrag.","code":"const betraege = [5, 8, 12]; const summe = betraege.reduce((gesamt, wert) => gesamt + wert, 0); console.log(summe);","erklaerung":"Die Ausgabe 25 lässt sich direkt durch 5 plus 8 plus 12 nachrechnen.","tiefer":["Teste reduce mit einer leeren Liste und mit einem einzigen Wert. Beide Fälle sollten ein sinnvolles Ergebnis liefern, hier 0 und den Wert selbst. Solche Randfälle zeigen schnell, ob der Startwert stimmt.","Für den Durchschnitt teilst du die Summe durch `betraege.length` – aber nur, wenn die Liste nicht leer ist, sonst entsteht `NaN`. Für den größten Wert gibt es auch die kürzere Form `Math.max(...betraege)`."]}],"beispiel":{"html":"<h1>Kassenabschluss</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Baue das Beispiel „Mit reduce Werte zusammenfassen“ nach. Prüfe die Konsole und ändere einen Beispielwert.","tipp":"Gib der Funktion absichtlich einen leeren oder ungültigen Wert und beobachte den Rückgabewert.","pruefungen":[{"beschreibung":"Die Übungsoberfläche ist vorhanden.","test":"p4-3-html"},{"beschreibung":"Die JavaScript-Technik wurde eingesetzt.","test":"p4-3-js"}],"loesung":{"html":"<h1>Kassenabschluss</h1><p id='ausgabe'></p>","css":"","js":"const betraege = [5, 8, 12]; const summe = betraege.reduce((gesamt, wert) => gesamt + wert, 0); console.log(summe);"}},"fehler":[{"titel":"Startwert als Text angegeben","text":"Falsch: `betraege.reduce((a,b) => a + b, '0')` ergibt `05812`, weil mit einem String begonnen wird. Die Konsole zeigt eine Zeichenkette statt 25. Richtig: `betraege.reduce((a,b) => a + b, 0)` liefert `25`."},{"titel":"Leeres Array ohne Startwert reduziert","text":"Falsch: `[].reduce((a,b) => a + b)` wirft `TypeError: Reduce of empty array with no initial value`. Richtig: `[].reduce((a,b) => a + b, 0)` liefert sicher `0`."}],"quiz":[{"frage":"Wozu dient gesamt?","antworten":["Als CSS-ID","Als Datei","Als Zwischenstand"],"richtig":2,"erklaerung":"Richtig ist „Als Zwischenstand“. Das folgt aus dem konkreten Verhalten von mit reduce werte zusammenfassen, das in Schritt 1 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Was ist der Startwert bei einer Summe?","antworten":["'0'","0","true"],"richtig":1,"erklaerung":"Richtig ist „0“. Das folgt aus dem konkreten Verhalten von mit reduce werte zusammenfassen, das in Schritt 2 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Was ergibt 5+8+12?","antworten":["25","12","20"],"richtig":0,"erklaerung":"Richtig ist „25“. Das folgt aus dem konkreten Verhalten von mit reduce werte zusammenfassen, das in Schritt 3 erläutert wird.","begruendungen":["Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]}],"merke":["reduce sammelt mehrere Zahlen in einem einzigen Ergebnis.","Ein numerischer Startwert sorgt auch bei einer leeren Liste für ein Ergebnis."],"explanation":"Fehlerhafte Daten sind im Alltag normal und müssen gezielt geprüft werden. Diese Lektion zeigt dir, wie du unerwartete Werte abfängst."},{"id":"p4-4","title":"JSON lesen und schreiben","minutes":30,"ziel":"Daten zwischen Text und JavaScript umwandeln","schritte":[{"titel":"Objekt und Datentext unterscheiden","text":"Ein Formular kann Angaben als Objekt im Programm speichern. `const person = { name: 'Amina', punkte: 4 };` enthält zwei Eigenschaften. Für eine Datei oder Übertragung wird oft ein Textformat benötigt. JSON beschreibt Daten als Text nach festen Regeln. Es ist keine ausführbare JavaScript-Datei.","code":"const person = { name: 'Amina', punkte: 4 }; const text = JSON.stringify(person); const wieder = JSON.parse(text); console.log(wieder.name);","erklaerung":"Ein JavaScript-Objekt ist noch kein JSON-Text für eine Datei.","tiefer":["JSON (JavaScript Object Notation) ist ein reines Textformat. Ein Objekt im Arbeitsspeicher kann nicht direkt in eine Datei oder über das Netz verschickt werden; es muss zuerst in Text umgewandelt werden. Dieser Vorgang heißt Serialisierung.","JSON ist strenger als JavaScript: Schlüssel und Texte stehen immer in doppelten Anführungszeichen, Kommentare und ein Komma nach dem letzten Eintrag sind verboten. Funktionen, `undefined` und Datumsobjekte gibt es in JSON nicht als eigene Typen."]},{"titel":"Mit stringify umwandeln","text":"Beim Versand wird eine Information in ein standardisiertes Format verpackt. `JSON.stringify(person)` erzeugt aus dem Objekt einen JSON-String. Die Eigenschaftsnamen erscheinen darin in doppelten Anführungszeichen. Funktionen werden dabei nicht wie normale Daten übertragen. Gib den erzeugten Text in der Konsole aus.","code":"const person = { name: 'Amina', punkte: 4 }; const text = JSON.stringify(person); const wieder = JSON.parse(text); console.log(wieder.name);","erklaerung":"stringify verpackt die Eigenschaften in eine standardisierte Zeichenkette.","tiefer":["`JSON.stringify` lässt Eigenschaften mit dem Wert `undefined` und Funktionen einfach weg. Datumsobjekte werden zu Texten im ISO-Format wie „2026-11-23T10:00:00.000Z“. Mit `JSON.stringify(person, null, 2)` entsteht ein eingerückter, gut lesbarer Text.","Enthält ein Objekt einen Verweis auf sich selbst, bricht `stringify` mit einem Fehler ab, weil der Text unendlich lang würde. Für normale Daten aus Formularen oder Listen passiert das nicht."]},{"titel":"Mit parse zurücklesen","text":"Beim Empfang wird das Paket wieder ausgepackt. `JSON.parse(text)` liest den JSON-String und erzeugt einen JavaScript-Wert. Mit `wieder.name` greifst du anschließend auf die Eigenschaft zu. parse erwartet gültiges JSON. Ein fehlendes Anführungszeichen kann einen SyntaxError auslösen.","code":"const person = { name: 'Amina', punkte: 4 }; const text = JSON.stringify(person); const wieder = JSON.parse(text); console.log(wieder.name);","erklaerung":"parse erzeugt aus gültigem JSON wieder einen nutzbaren JavaScript-Wert.","tiefer":["`JSON.parse` erzeugt ein völlig neues Objekt. Es ist unabhängig vom ursprünglichen Objekt; Änderungen wirken nicht aufeinander. Deshalb wurde `JSON.parse(JSON.stringify(obj))` früher oft als Trick für tiefe Kopien benutzt – heute nimmt man `structuredClone`.","Ist der Text kein gültiges JSON, wirft `parse` einen SyntaxError. Schon ein einfaches Anführungszeichen statt eines doppelten reicht dafür. Darum gehört `JSON.parse` bei Daten aus unsicheren Quellen in einen try-catch-Block."]},{"titel":"Daten vorsichtig prüfen","text":"Ein Paket von außen kann unvollständig oder falsch aufgebaut sein. Prüfe nach dem Parsen, ob die erwarteten Eigenschaften existieren. `typeof wieder.name === 'string'` kontrolliert beispielsweise den Namen. Vertraue fremden Daten nicht automatisch. Zeige unbekannte Texte nur über textContent an.","code":"const person = { name: 'Amina', punkte: 4 }; const text = JSON.stringify(person); const wieder = JSON.parse(text); console.log(wieder.name);","erklaerung":"Der Typ des Namens wird vor der Weiterverarbeitung kontrolliert.","tiefer":["Daten von außen können fehlen, einen falschen Typ haben oder absichtlich manipuliert sein. Prüfe deshalb jede Eigenschaft, die du benutzt, und lege für fehlende Werte sinnvolle Standards fest. Diese Prüfung heißt Validierung.","Für größere Projekte gibt es Bibliotheken, die erwartete Datenstrukturen als Schema beschreiben und automatisch prüfen. Das Prinzip bleibt gleich: Vertraue keinen Daten, die nicht aus deinem eigenen Programm stammen, und zeige sie mit `textContent` statt `innerHTML` an."]}],"beispiel":{"html":"<h1>JSON-Daten</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Baue das Beispiel „JSON lesen und schreiben“ nach. Prüfe die Konsole und ändere einen Beispielwert.","tipp":"Vergleiche vor und nach JSON.stringify die Typen deiner Daten.","pruefungen":[{"beschreibung":"Die Übungsoberfläche ist vorhanden.","test":"p4-4-html"},{"beschreibung":"Die JavaScript-Technik wurde eingesetzt.","test":"p4-4-js"}],"loesung":{"html":"<h1>JSON-Daten</h1><p id='ausgabe'></p>","css":"","js":"const person = { name: 'Amina', punkte: 4 }; const text = JSON.stringify(person); const wieder = JSON.parse(text); console.log(wieder.name);"}},"fehler":[{"titel":"Objekt direkt an parse übergeben","text":"Falsch: `JSON.parse({name:'Amina'})` erzeugt einen SyntaxError, weil parse einen JSON-String erwartet. Richtig: `JSON.parse('{\"name\":\"Amina\"}')` liefert ein Objekt mit der Eigenschaft name."},{"titel":"Ungültige Anführungszeichen im JSON","text":"Falsch: `JSON.parse(\"{'name':'Amina'}\")` wirft einen SyntaxError, weil JSON doppelte Anführungszeichen verlangt. Richtig: `JSON.parse('{\"name\":\"Amina\"}')` lässt sich erfolgreich lesen."}],"quiz":[{"frage":"Was erzeugt stringify?","antworten":["JSON-Text","Ein DOM-Element","Eine Schleife"],"richtig":0,"erklaerung":"Richtig ist „JSON-Text“. Das folgt aus dem konkreten Verhalten von json lesen und schreiben, das in Schritt 1 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]},{"frage":"Was macht parse?","antworten":["Speichert CSS","Liest JSON-Text","Öffnet GitHub"],"richtig":1,"erklaerung":"Richtig ist „Liest JSON-Text“. Das folgt aus dem konkreten Verhalten von json lesen und schreiben, das in Schritt 2 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Was braucht JSON für Eigenschaftsnamen?","antworten":["Keine Zeichen","Einfache Quotes","Doppelte Anführungszeichen"],"richtig":2,"erklaerung":"Richtig ist „Doppelte Anführungszeichen“. Das folgt aus dem konkreten Verhalten von json lesen und schreiben, das in Schritt 3 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]}],"merke":["JSON.stringify erzeugt einen Datentext aus einem JavaScript-Wert.","JSON.parse benötigt syntaktisch gültigen JSON-Text."],"explanation":"Strukturierte Daten erleichtern den Austausch zwischen Funktionen und Programmen. Du übst, Objekte und JSON gezielt einzusetzen."},{"id":"p4-5","title":"localStorage für Einstellungen","minutes":30,"ziel":"Eine lokale Einstellung im Browser speichern","schritte":[{"titel":"Eine Einstellung festlegen","text":"Wie ein Lesezeichen soll eine kleine Einstellung nach dem Neuladen erhalten bleiben. `const thema = 'hell';` speichert zunächst einen Text im laufenden Programm. Nach dem Schließen wäre diese Variable verschwunden. Der Browser bietet für einfache lokale Werte localStorage. Speichere dort keine Passwörter oder vertraulichen Daten.","code":"const thema = 'hell'; localStorage.setItem('thema', thema); const gespeichert = localStorage.getItem('thema'); console.log(gespeichert);","erklaerung":"Eine lokale Theme-Einstellung überlebt einen Seitenneustart im selben Browser.","tiefer":["Variablen leben nur, solange die Seite geöffnet ist. Beim Neuladen beginnt das Skript von vorn, und alle Werte sind weg. Für kleine Einstellungen wie Farbschema oder Sprache bietet der Browser dauerhaften Speicher an.","Neben `localStorage` gibt es `sessionStorage`, dessen Inhalt beim Schließen des Tabs gelöscht wird. Für größere oder strukturierte Datenmengen eignet sich IndexedDB. Alle drei speichern nur im Browser auf dem jeweiligen Gerät."]},{"titel":"Einen Wert ablegen","text":"Ein Schließfach hat einen Namen und einen Inhalt. `localStorage.setItem('thema', thema)` legt den Wert unter dem Schlüssel thema ab. Beide Angaben werden als Text gespeichert. Der Schlüssel hilft, die Einstellung später wiederzufinden. Probiere einen anderen Wert aus und lade die Seite neu.","code":"const thema = 'hell'; localStorage.setItem('thema', thema); const gespeichert = localStorage.getItem('thema'); console.log(gespeichert);","erklaerung":"setItem legt den Schlüssel thema mit einem Textwert im lokalen Speicher ab.","tiefer":["localStorage speichert ausschließlich Texte. Zahlen oder Booleans werden beim Speichern zu Texten – `true` wird zu `'true'`. Objekte und Arrays wandelst du vorher mit `JSON.stringify` um und beim Lesen mit `JSON.parse` zurück.","Der Speicher ist begrenzt, meist auf etwa 5 MB pro Webseite. Ist er voll oder blockiert, etwa im privaten Modus mancher Browser, wirft `setItem` einen Fehler. Schreibe den Zugriff deshalb in einen try-catch-Block, damit die Seite trotzdem funktioniert."]},{"titel":"Eine Einstellung lesen","text":"Ein Schließfach wird mit seinem Namen wiedergefunden. `localStorage.getItem('thema')` liest den gespeicherten Text. Ist kein Eintrag vorhanden, liefert die Methode null. Mit `const gespeichert = ...` kannst du das Ergebnis weiterverwenden. Prüfe vor einer Anzeige, ob wirklich ein Wert existiert.","code":"const thema = 'hell'; localStorage.setItem('thema', thema); const gespeichert = localStorage.getItem('thema'); console.log(gespeichert);","erklaerung":"getItem liefert einen gespeicherten String oder bei fehlendem Schlüssel null.","tiefer":["Ein fehlender Eintrag liefert `null`. Mit `localStorage.getItem('thema') ?? 'hell'` legst du einen Standardwert fest, falls noch nichts gespeichert wurde. So funktioniert die Seite auch beim allerersten Besuch.","Gespeicherte Werte können veraltet oder von Hand verändert sein, denn jeder kann sie in den Entwicklerwerkzeugen unter „Anwendung“ bearbeiten. Prüfe deshalb, ob ein gelesener Wert erlaubt ist, bevor du ihn verwendest."]},{"titel":"Grenzen und Löschen kennen","text":"Ein gemeinsam benutzter Computer kann lokale Einstellungen anderer Menschen enthalten. `localStorage.removeItem('thema')` löscht genau diesen Eintrag. Die Daten liegen im Browser und werden nicht automatisch zwischen Geräten synchronisiert. In privaten oder eingeschränkten Umgebungen kann der Zugriff scheitern. Fange mögliche Speicherfehler ab.","code":"const thema = 'hell'; localStorage.setItem('thema', thema); const gespeichert = localStorage.getItem('thema'); console.log(gespeichert);","erklaerung":"removeItem entfernt genau die angegebene Einstellung aus dem Browser.","tiefer":["Jede Webseite hat ihren eigenen Speicherbereich; andere Seiten können ihn nicht lesen. Diese Trennung nach Herkunft heißt Same-Origin-Policy. Skripte auf derselben Seite können ihn allerdings lesen – auch eingeschleuster Schadcode.","Speichere deshalb niemals Passwörter, Zugangsschlüssel oder sensible persönliche Daten im localStorage. Mit `localStorage.clear()` löschst du alle Einträge der Seite auf einmal. Nutzer können den Speicher jederzeit über die Browsereinstellungen leeren."]}],"beispiel":{"html":"<h1>Ansicht merken</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Baue das Beispiel „localStorage für Einstellungen“ nach. Prüfe die Konsole und ändere einen Beispielwert.","tipp":"Zeige während des Wartens einen Ladehinweis und prüfe auch den Fehlerfall.","pruefungen":[{"beschreibung":"Die Übungsoberfläche ist vorhanden.","test":"p4-5-html"},{"beschreibung":"Die JavaScript-Technik wurde eingesetzt.","test":"p4-5-js"}],"loesung":{"html":"<h1>Ansicht merken</h1><p id='ausgabe'></p>","css":"","js":"const thema = 'hell'; localStorage.setItem('thema', thema); const gespeichert = localStorage.getItem('thema'); console.log(gespeichert);"}},"fehler":[{"titel":"Fehlenden Schlüssel als Text behandeln","text":"Falsch: `localStorage.getItem('unbekannt').toUpperCase()` kann `TypeError: Cannot read properties of null` auslösen. Richtig: `const wert = localStorage.getItem('unbekannt'); if (wert !== null) console.log(wert.toUpperCase());`."},{"titel":"Objekt ohne JSON speichern","text":"Falsch: `localStorage.setItem('profil', {name:'Amina'})` speichert den Text `[object Object]`, nicht die Eigenschaften. Richtig: `localStorage.setItem('profil', JSON.stringify({name:'Amina'}))`; beim Lesen `JSON.parse(...)` verwenden."}],"quiz":[{"frage":"Wo liegen die Werte?","antworten":["In jedem GitHub-Repo","Im lokalen Browser","In einer PDF"],"richtig":1,"erklaerung":"Richtig ist „Im lokalen Browser“. Das folgt aus dem konkreten Verhalten von localstorage für einstellungen, das in Schritt 1 erläutert wird.","begruendungen":["Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Was liefert getItem bei fehlendem Schlüssel?","antworten":["false","0","null"],"richtig":2,"erklaerung":"Richtig ist „null“. Das folgt aus dem konkreten Verhalten von localstorage für einstellungen, das in Schritt 2 erläutert wird.","begruendungen":["Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Wie löschst du einen Schlüssel?","antworten":["removeItem('thema')","deleteStorage()","clearHTML()"],"richtig":0,"erklaerung":"Richtig ist „removeItem('thema')“. Das folgt aus dem konkreten Verhalten von localstorage für einstellungen, das in Schritt 3 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]}],"merke":["localStorage speichert Text lokal im aktuellen Browserprofil.","Vertrauliche Informationen gehören nicht in localStorage."],"explanation":"Asynchrone Abläufe bestimmen, wann Daten verfügbar sind und wann eine Anzeige aktualisiert werden darf. Du lernst, die Reihenfolge nachvollziehbar zu steuern."},{"id":"p4-6","title":"JavaScript-Module verwenden","minutes":30,"ziel":"Funktionen mit import und export aufteilen","schritte":[{"titel":"Dateien nach Aufgaben trennen","text":"Eine Werkstatt hat verschiedene Schubladen für unterschiedliche Werkzeuge. In einem Webprojekt können Berechnungen und Bedienoberfläche ebenfalls getrennt sein. `rechner.mjs` enthält die Rechenfunktion. `app.mjs` kümmert sich um ihre Verwendung. So bleibt jede Datei überschaubar.","code":"/* rechner.mjs */ export function doppelt(x) { return x * 2; }\n/* app.mjs */ import { doppelt } from './rechner.mjs'; console.log(doppelt(5));","erklaerung":"Die Berechnung wird in eine separate Moduldatei ausgelagert.","tiefer":["Module teilen Code in überschaubare Dateien mit klarer Aufgabe. Jedes Modul hat einen eigenen Gültigkeitsbereich: Variablen darin sind außen unsichtbar, solange sie nicht exportiert werden. So stören sich gleiche Namen in verschiedenen Dateien nicht.","Die Endung `.mjs` kennzeichnet ausdrücklich ein JavaScript-Modul; im Browser funktioniert auch `.js`, wenn das Skript als Modul geladen wird. Module laufen automatisch im strikten Modus, der einige fehleranfällige alte Schreibweisen verbietet."]},{"titel":"Mit export freigeben","text":"Ein Werkzeug wird erst nutzbar, wenn es aus der Schublade herausgegeben wird. `export function doppelt(x) { return x * 2; }` macht die Funktion für andere Module verfügbar. Das Wort export steht vor der Definition. Der Funktionsname bleibt doppelt. Ohne Export kann ein anderes Modul sie nicht so importieren.","code":"/* rechner.mjs */ export function doppelt(x) { return x * 2; }\n/* app.mjs */ import { doppelt } from './rechner.mjs'; console.log(doppelt(5));","erklaerung":"Der benannte Export macht doppelt für andere Module verfügbar.","tiefer":["Neben benannten Exporten gibt es einen Standardexport pro Datei: `export default function doppelt(x) { ... }`. Beim Import schreibt man ihn ohne geschweifte Klammern und darf ihn beliebig benennen. Benannte Exporte sind oft klarer, weil der Name überall gleich bleibt.","Du kannst auch am Ende der Datei gesammelt exportieren: `export { doppelt, halbiert };`. Nur das Exportierte ist von außen erreichbar – alles andere bleibt ein internes Detail, das du später frei ändern kannst."]},{"titel":"Mit import verwenden","text":"Eine Kollegin holt genau das benötigte Werkzeug. `import { doppelt } from './rechner.mjs';` lädt die benannte Funktion aus der relativen Datei. Die geschweiften Klammern bezeichnen einen benannten Export. Der Pfad beginnt hier mit Punkt und Schrägstrich. Ein falscher Dateiname führt zu einem Ladefehler.","code":"/* rechner.mjs */ export function doppelt(x) { return x * 2; }\n/* app.mjs */ import { doppelt } from './rechner.mjs'; console.log(doppelt(5));","erklaerung":"Der relative Importpfad verweist auf die Datei neben dem Hauptmodul.","tiefer":["Beim Import im Browser muss der Pfad mit `./`, `../` oder `/` beginnen und die Dateiendung enthalten. Ein bloßer Paketname wie `'lodash'` funktioniert nur mit Werkzeugen wie Bundlern oder einer Import-Map. Mit `as` kannst du umbenennen: `import { doppelt as x2 } from ...`.","Ein Modul wird nur einmal geladen und ausgeführt, auch wenn mehrere Dateien es importieren. Mit `import()` als Funktion lädst du ein Modul erst bei Bedarf nach – praktisch für selten genutzte Funktionen."]},{"titel":"Module im Browser starten","text":"Ein Modul benötigt im HTML einen passenden Skripttyp. `<script type='module' src='./app.mjs'></script>` startet die Hauptdatei. Module werden im Browser standardmäßig verzögert ausgeführt. Öffne das Projekt über einen lokalen Webserver statt über einen unzuverlässigen file-Pfad. Kontrolliere Ladefehler in der Konsole.","code":"/* rechner.mjs */ export function doppelt(x) { return x * 2; }\n/* app.mjs */ import { doppelt } from './rechner.mjs'; console.log(doppelt(5));","erklaerung":"type=module ist erforderlich, damit der Browser Import-Anweisungen versteht.","tiefer":["`type='module'` sorgt dafür, dass das Skript wie mit `defer` erst nach dem Einlesen des HTML ausgeführt wird. Außerdem gelten für Module strengere Sicherheitsregeln: Sie werden über HTTP geladen und funktionieren deshalb nicht, wenn du die HTML-Datei direkt per Doppelklick öffnest.","Für die lokale Entwicklung brauchst du einen kleinen Webserver, zum Beispiel die Live-Server-Erweiterung im Code-Editor oder `python -m http.server`. Die Fehlermeldung „CORS“ in der Konsole zeigt meist genau dieses Problem an."]}],"beispiel":{"html":"<h1>Module organisieren</h1><p id='ausgabe'></p>","css":"","js":""},"aufgabe":{"text":"Baue das Beispiel „JavaScript-Module verwenden“ nach. Prüfe die Konsole und ändere einen Beispielwert. Für import und export benötigst du zwei echte Moduldateien und eine HTML-Datei mit type='module'; die eingebettete Ein-Datei-Vorschau führt diese Modulstruktur nicht direkt aus. Das vollständige ausführbare Beispiel liegt unter /mein-sd-hub/p4-module/index.html.","tipp":"Teile das Projekt in Eingabe, Verarbeitung und Ausgabe und teste jede Aufgabe einzeln.","pruefungen":[{"beschreibung":"Die Übungsoberfläche ist vorhanden.","test":"p4-6-html"},{"beschreibung":"Die JavaScript-Technik wurde eingesetzt.","test":"p4-6-js"}],"loesung":{"html":"<h1>Module organisieren</h1><p id='ausgabe'></p>","css":"","js":"/* rechner.mjs */ export function doppelt(x) { return x * 2; }\n/* app.mjs */ import { doppelt } from './rechner.mjs'; console.log(doppelt(5));"}},"fehler":[{"titel":"Benannten Export ohne Klammern importiert","text":"Falsch: `import doppelt from './rechner.mjs';` meldet, dass kein default-Export vorhanden ist, wenn nur `export function doppelt` definiert wurde. Richtig: `import { doppelt } from './rechner.mjs';`."},{"titel":"Modul als normales Script geladen","text":"Falsch: `<script src='./app.mjs'></script>` kann `SyntaxError: Cannot use import statement outside a module` auslösen. Richtig: `<script type='module' src='./app.mjs'></script>` aktiviert die Modulsyntax."}],"quiz":[{"frage":"Was macht export?","antworten":["Löscht die Datei","Startet den Server","Macht einen Wert importierbar"],"richtig":2,"erklaerung":"Richtig ist „Macht einen Wert importierbar“. Das folgt aus dem konkreten Verhalten von javascript-module verwenden, das in Schritt 1 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Was bedeutet './rechner.mjs'?","antworten":["Ein relativer Dateipfad","Ein CSS-Selektor","Eine Internetadresse"],"richtig":0,"erklaerung":"Richtig ist „Ein relativer Dateipfad“. Das folgt aus dem konkreten Verhalten von javascript-module verwenden, das in Schritt 2 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]},{"frage":"Welcher Skripttyp wird benötigt?","antworten":["text/plain","module","classic"],"richtig":1,"erklaerung":"Richtig ist „module“. Das folgt aus dem konkreten Verhalten von javascript-module verwenden, das in Schritt 3 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]}],"merke":["Ein benannter Export wird mit geschweiften Klammern importiert.","Ein Browsermodul wird mit type=module geladen."],"projektLink":"/mein-sd-hub/p4-module/index.html","explanation":"Eine größere Anwendung profitiert von klar getrennten Verantwortlichkeiten. Du setzt mehrere Techniken in einem überschaubaren Projekt zusammen."},{"id":"p4-7","title":"fetch und async/await","minutes":30,"ziel":"Eine lokale JSON-Datei asynchron laden","schritte":[{"titel":"Eine lokale Datei bereitstellen","text":"Eine Bibliothek verwahrt Fragen in einem eigenen Ordner. Lege `daten/fragen.json` innerhalb des Projekts ab. Der Inhalt ist gültiges JSON und wird vom Webserver bereitgestellt. Du brauchst dafür keinen externen Dienst. Prüfe den Dateipfad vor dem Programmieren.","code":"async function laden() { const antwort = await fetch('./daten/fragen.json'); if (!antwort.ok) throw new Error('Datei nicht geladen'); const fragen = await antwort.json(); console.log(fragen); } laden().catch(console.error);","erklaerung":"Die Fragen stehen in einer Datei, die vom lokalen Webserver ausgeliefert wird.","tiefer":["Webseiten laden Daten oft nachträglich, ohne die ganze Seite neu zu laden. Eine JSON-Datei im Projekt ist der einfachste Fall: Sie wird vom selben Server ausgeliefert wie die Seite. Später können an derselben Stelle Antworten echter Schnittstellen stehen.","Der Pfad `./daten/fragen.json` ist relativ zur HTML-Seite. Achte auf exakte Schreibweise – viele Webserver unterscheiden Groß- und Kleinschreibung, auch wenn dein Computer es nicht tut. Ein falscher Pfad führt zu einem 404-Fehler."]},{"titel":"Mit fetch anfragen","text":"Ein Bibliotheksmitarbeiter holt die angeforderte Datei aus dem Regal. `fetch('./daten/fragen.json')` startet eine HTTP-Anfrage an den lokalen Server. Das Ergebnis ist zunächst ein Promise. Die Anfrage kann Zeit benötigen. Deshalb darfst du nicht sofort mit fertigen Daten rechnen.","code":"async function laden() { const antwort = await fetch('./daten/fragen.json'); if (!antwort.ok) throw new Error('Datei nicht geladen'); const fragen = await antwort.json(); console.log(fragen); } laden().catch(console.error);","erklaerung":"fetch startet die Anfrage, während der restliche Browser bedienbar bleibt.","tiefer":["Ein Promise ist ein Versprechen auf ein späteres Ergebnis. Es kann drei Zustände haben: ausstehend, erfüllt oder abgelehnt. Während die Anfrage läuft, arbeitet der Browser weiter – die Seite bleibt bedienbar.","Diese Arbeitsweise heißt asynchron. JavaScript im Browser hat nur einen Haupt-Thread; würde es auf langsame Netzwerkanfragen warten, wäre die Seite währenddessen eingefroren. Die Ereignisschleife (Event Loop) setzt die Arbeit fort, sobald das Ergebnis da ist."]},{"titel":"Mit await warten","text":"Beim Abholen wartest du, bis die Datei tatsächlich angekommen ist. `const antwort = await fetch('./daten/fragen.json');` wartet innerhalb einer async-Funktion auf die Antwort. `await antwort.json()` liest anschließend den JSON-Inhalt. Beide Schritte können scheitern. Gib die gelesenen Fragen erst danach aus.","code":"async function laden() { const antwort = await fetch('./daten/fragen.json'); if (!antwort.ok) throw new Error('Datei nicht geladen'); const fragen = await antwort.json(); console.log(fragen); } laden().catch(console.error);","erklaerung":"await wartet zuerst auf die Antwort und anschließend auf das Lesen der JSON-Daten.","tiefer":["`await` darf nur in einer mit `async` gekennzeichneten Funktion stehen (in Modulen auch auf oberster Ebene). Es unterbricht nur diese Funktion, nicht die ganze Seite. Eine async-Funktion gibt selbst immer ein Promise zurück.","`antwort.json()` ist ebenfalls asynchron, weil der Inhalt noch übertragen wird, während die Kopfzeilen der Antwort schon da sind. Deshalb braucht es ein zweites `await`. Brauchst du nur Text, nimm `antwort.text()`."]},{"titel":"Antwort und Fehler prüfen","text":"Auch eine fehlende Datei kann eine HTTP-Antwort liefern. `if (!antwort.ok) throw new Error('Datei nicht geladen');` prüft den Status. `laden().catch(console.error)` macht Fehler sichtbar. Zeige bei einer echten App eine verständliche Meldung in der Oberfläche. Teste bewusst einen falschen Dateinamen.","code":"async function laden() { const antwort = await fetch('./daten/fragen.json'); if (!antwort.ok) throw new Error('Datei nicht geladen'); const fragen = await antwort.json(); console.log(fragen); } laden().catch(console.error);","erklaerung":"Ein fehlender HTTP-Erfolg wird vor dem Aufruf von json als Fehler behandelt.","tiefer":["`fetch` lehnt das Promise nur bei Netzwerkfehlern ab, zum Beispiel ohne Internetverbindung. Eine Antwort mit Status 404 oder 500 gilt als erfolgreiche Übertragung. Darum musst du `antwort.ok` selbst prüfen – es ist bei Statuscodes von 200 bis 299 wahr.","Wichtige Statuscodes: 200 bedeutet OK, 404 nicht gefunden, 500 Serverfehler. Ein unbehandeltes abgelehntes Promise erscheint in der Konsole als „Uncaught (in promise)“. Zeige Nutzern statt technischer Details eine verständliche Meldung mit einem Vorschlag, was sie tun können."]}],"beispiel":{"html":"<h1>Lokale Fragen laden</h1><p id='ausgabe'>Daten werden geladen.</p>","css":"","js":""},"aufgabe":{"text":"Baue das Beispiel „fetch und async/await“ nach. Prüfe die Konsole und ändere einen Beispielwert.","tipp":"Probiere eine ungültige Benutzereingabe aus und kontrolliere die sichtbare Fehlermeldung.","pruefungen":[{"beschreibung":"Die Übungsoberfläche ist vorhanden.","test":"p4-7-html"},{"beschreibung":"Die JavaScript-Technik wurde eingesetzt.","test":"p4-7-js"}],"loesung":{"html":"<h1>Lokale Fragen laden</h1><p id='ausgabe'>Daten werden geladen.</p>","css":"","js":"async function laden() { const antwort = await fetch('./daten/fragen.json'); if (!antwort.ok) throw new Error('Datei nicht geladen'); const fragen = await antwort.json(); console.log(fragen); } laden().catch(console.error);"}},"fehler":[{"titel":"JSON vor Abschluss der Anfrage verwendet","text":"Falsch: `const fragen = fetch('./daten/fragen.json'); console.log(fragen[0]);` liefert keinen ersten Eintrag, sondern arbeitet mit einem Promise. Richtig: `const antwort = await fetch('./daten/fragen.json'); const fragen = await antwort.json();` innerhalb einer async-Funktion."},{"titel":"HTTP-Fehler nicht geprüft","text":"Falsch: `const r = await fetch('./daten/fehlt.json'); const d = await r.json();` kann bei einer 404-HTML-Seite einen JSON-Syntaxfehler auslösen. Richtig: `if (!r.ok) throw new Error('HTTP ' + r.status);` vor `r.json()`."}],"quiz":[{"frage":"Was liefert fetch zuerst?","antworten":["Ein Promise","Immer ein Array","Einen CSS-Wert"],"richtig":0,"erklaerung":"Richtig ist „Ein Promise“. Das folgt aus dem konkreten Verhalten von fetch und async/await, das in Schritt 1 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]},{"frage":"Wo darf await stehen?","antworten":["In jeder normalen Funktion","In einer async-Funktion oder auf Modulebene","Nur im HTML"],"richtig":1,"erklaerung":"Richtig ist „In einer async-Funktion oder auf Modulebene“. Das folgt aus dem konkreten Verhalten von fetch und async/await, das in Schritt 2 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt."]},{"frage":"Was prüft antwort.ok?","antworten":["Ob die HTTP-Antwort erfolgreich war","Die Schriftgröße","Den Dateinamen"],"richtig":0,"erklaerung":"Richtig ist „Ob die HTTP-Antwort erfolgreich war“. Das folgt aus dem konkreten Verhalten von fetch und async/await, das in Schritt 3 erläutert wird.","begruendungen":["Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]}],"merke":["fetch lädt die JSON-Datei vom eigenen Projektserver.","await und die Prüfung von response.ok gehören zu einem robusten Ladevorgang."],"explanation":"Eine gute Oberfläche muss auch bei ungültigen Eingaben und ungewöhnlichen Situationen funktionieren. Du lernst, Fehler sichtbar und verständlich zu behandeln."},{"id":"p4-8","title":"try/catch und Quiz-App","minutes":30,"ziel":"Fehler behandeln und ein kleines Quiz aus lokalen Daten anzeigen","schritte":[{"titel":"Ein kleines Quiz planen","text":"Ein Quiz ist wie ein Stapel Fragekarten mit mehreren Antworten. Die Karten liegen in `daten/fragen.json` als Liste von Objekten. Jede Karte enthält einen Fragetext und mögliche Antworten. Die Webseite zeigt zunächst nur einen Startknopf. Halte Daten und Darstellung getrennt.","code":"async function quizStarten() { try { const r = await fetch('./daten/fragen.json'); if (!r.ok) throw new Error('Fragen fehlen'); const fragen = await r.json(); const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = fragen[0].frage; } catch (fehler) { const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Quiz konnte nicht geladen werden.'; console.error(fehler); } } quizStarten();","erklaerung":"Die Quizfragen sind von der Oberfläche getrennte strukturierte Daten.","tiefer":["Eine typische Struktur für jede Frage: `{ \"frage\": \"...\", \"antworten\": [\"A\", \"B\", \"C\"], \"richtig\": 1 }`. Die Position der richtigen Antwort steht als Zahl im Feld `richtig`. Durch die Trennung von Daten und Code kannst du Fragen ändern, ohne das Programm anzufassen.","Plane die Zustände der App: lädt, Frage wird angezeigt, Antwort gewählt, Quiz beendet, Fehler. Jeder Zustand bestimmt, was auf dem Bildschirm zu sehen ist. Wer die Zustände vorher aufschreibt, vergisst seltener einen Fall."]},{"titel":"Fragen sicher laden","text":"Eine Fragekarte muss erst aus dem Stapel geholt werden. `const r = await fetch('./daten/fragen.json');` fordert die lokale Datei an. `if (!r.ok)` erkennt einen HTTP-Fehler. `await r.json()` liest die Liste. Prüfe danach, ob wenigstens eine Frage vorhanden ist.","code":"async function quizStarten() { try { const r = await fetch('./daten/fragen.json'); if (!r.ok) throw new Error('Fragen fehlen'); const fragen = await r.json(); const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = fragen[0].frage; } catch (fehler) { const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Quiz konnte nicht geladen werden.'; console.error(fehler); } } quizStarten();","erklaerung":"Der Ladevorgang liest die Fragendatei und prüft die Antwort des Servers.","tiefer":["Prüfe nach dem Laden, ob die Daten wirklich ein Array sind und mindestens eine Frage enthalten: `if (!Array.isArray(fragen) || fragen.length === 0)`. Jede Frage sollte einen Text und ein Array von Antworten haben. So stürzt die App nicht ab, wenn die Datei fehlerhaft ist.","Zeige während des Ladens einen Hinweis wie „Fragen werden geladen …“. Auf langsamen Verbindungen kann das einige Sekunden dauern. Ohne Rückmeldung halten Nutzer die Seite sonst für kaputt."]},{"titel":"Mit try/catch reagieren","text":"Auch eine sorgfältig gebaute App kann eine fehlende Datei antreffen. `try { ... }` umfasst die riskanten Anweisungen. `catch (fehler) { ... }` reagiert auf eine Ausnahme. Die Konsole zeigt technische Details, die Oberfläche einen verständlichen Hinweis. So bleibt die App auch bei Problemen bedienbar.","code":"async function quizStarten() { try { const r = await fetch('./daten/fragen.json'); if (!r.ok) throw new Error('Fragen fehlen'); const fragen = await r.json(); const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = fragen[0].frage; } catch (fehler) { const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Quiz konnte nicht geladen werden.'; console.error(fehler); } } quizStarten();","erklaerung":"catch zeigt eine verständliche Fehlermeldung statt einer leeren Quizfläche.","tiefer":["Alles, was im `try`-Block schiefgeht – auch ein `throw` in `fetch`-Prüfungen oder ein JSON-Fehler – landet im `catch`. Ein optionaler `finally`-Block läuft immer, etwa um den Ladehinweis auszublenden. Mit `throw new Error('...')` kannst du selbst Fehler auslösen.","Trenne die technische Meldung für Entwickler (`console.error(fehler)`) von der freundlichen Meldung für Nutzer auf der Seite. Biete wenn möglich einen Ausweg an, etwa einen Knopf „Erneut versuchen“, der `laden()` noch einmal aufruft."]},{"titel":"Eine Frage anzeigen","text":"Eine Karte wird auf den Tisch gelegt, ohne ihren Text als HTML auszuführen. `ausgabe.textContent = fragen[0].frage;` zeigt die erste Frage sicher an. Ein späterer Schritt kann Antwortknöpfe und eine Punktezahl ergänzen. Teste die richtige Datei und anschließend eine absichtlich fehlende Datei. Achte darauf, dass die Statusmeldung lesbar bleibt.","code":"async function quizStarten() { try { const r = await fetch('./daten/fragen.json'); if (!r.ok) throw new Error('Fragen fehlen'); const fragen = await r.json(); const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = fragen[0].frage; } catch (fehler) { const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Quiz konnte nicht geladen werden.'; console.error(fehler); } } quizStarten();","erklaerung":"textContent zeigt die Frage an, ohne HTML aus dem Datensatz auszuführen.","tiefer":["Für die Antwortknöpfe erzeugst du pro Antwort einen `button` mit `textContent`. Ein Listener vergleicht die Position der gewählten Antwort mit `richtig`, zeigt eine Rückmeldung und erhöht gegebenenfalls einen Punktezähler. Danach geht es zur nächsten Frage.","Ein Index `aktuelleFrage` merkt sich die Position im Fragenstapel. Ist er gleich `fragen.length`, ist das Quiz beendet, und du zeigst das Ergebnis. Dieselbe Funktion `zeigeFrage()` kann so für jede Frage wiederverwendet werden – genau so ist auch die Akademie aufgebaut, in der du gerade lernst."]}],"beispiel":{"html":"<h1>Meine Quiz-App</h1><button id='start' type='button'>Quiz starten</button><p id='ausgabe' role='status'>Bereit.</p>","css":"","js":""},"aufgabe":{"text":"Baue das Beispiel „try/catch und Quiz-App“ nach. Prüfe die Konsole und ändere einen Beispielwert. Öffne das vollständige Projekt unter /mein-sd-hub/p4-quiz.html in einem eigenen Browser-Tab. Die eingebettete Editor-Vorschau besitzt aus Sicherheitsgründen eine isolierte Herkunft und kann lokale JSON-Dateien nicht direkt laden.","tipp":"Teste das Abschlussprojekt mit mehreren Eingaben und überprüfe die Reihenfolge der Ergebnisse.","pruefungen":[{"beschreibung":"Die Übungsoberfläche ist vorhanden.","test":"p4-8-html"},{"beschreibung":"Die JavaScript-Technik wurde eingesetzt.","test":"p4-8-js"}],"loesung":{"html":"<h1>Meine Quiz-App</h1><button id='start' type='button'>Quiz starten</button><p id='ausgabe' role='status'>Bereit.</p>","css":"","js":"async function quizStarten() { try { const r = await fetch('./daten/fragen.json'); if (!r.ok) throw new Error('Fragen fehlen'); const fragen = await r.json(); const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = fragen[0].frage; } catch (fehler) { const ausgabe = document.querySelector('#ausgabe'); if (ausgabe) ausgabe.textContent = 'Quiz konnte nicht geladen werden.'; console.error(fehler); } } quizStarten();"}},"fehler":[{"titel":"catch ohne hilfreiche Rückmeldung","text":"Falsch: `try { await laden(); } catch (e) {}` lässt bei einem Fehler eine leere Oberfläche zurück; Nutzer sehen keine Erklärung. Richtig: `catch (e) { ausgabe.textContent = 'Fragen konnten nicht geladen werden.'; console.error(e); }`."},{"titel":"Fragetext mit innerHTML angezeigt","text":"Falsch: `ausgabe.innerHTML = fragen[0].frage;` kann HTML aus einer Datei als echte Elemente interpretieren. Richtig: `ausgabe.textContent = fragen[0].frage;` zeigt den Inhalt als Text, auch wenn darin `<b>` vorkommt."}],"quiz":[{"frage":"Wozu dient catch?","antworten":["Zum Erzeugen von CSS","Zum Behandeln einer Ausnahme","Zum Speichern eines Branches"],"richtig":1,"erklaerung":"Richtig ist „Zum Behandeln einer Ausnahme“. Das folgt aus dem konkreten Verhalten von try/catch und quiz-app, das in Schritt 1 erläutert wird.","begruendungen":["Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Wie zeigst du Fragetext sicher?","antworten":["Mit eval","Mit document.write","Mit textContent"],"richtig":2,"erklaerung":"Richtig ist „Mit textContent“. Das folgt aus dem konkreten Verhalten von try/catch und quiz-app, das in Schritt 2 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]},{"frage":"Was sollte bei fehlender Datei passieren?","antworten":["Eine leere Seite","Eine Endlosschleife","Eine verständliche Fehlermeldung"],"richtig":2,"erklaerung":"Richtig ist „Eine verständliche Fehlermeldung“. Das folgt aus dem konkreten Verhalten von try/catch und quiz-app, das in Schritt 3 erläutert wird.","begruendungen":["Diese Aussage widerspricht der gezeigten JavaScript-Anweisung.","Diese Aussage beschreibt das gezeigte Verhalten korrekt.","Diese Aussage widerspricht der gezeigten JavaScript-Anweisung."]}],"merke":["try/catch fängt Fehler beim Laden und Verarbeiten der Quizfragen ab.","textContent hält die Ausgabe von Fragetexten von HTML-Markup getrennt."],"projektLink":"/mein-sd-hub/p4-quiz.html","explanation":"Zum Abschluss kombinierst du die Grundlagen zu einem nachvollziehbaren Projekt. Du überprüfst dabei Funktion, Verständlichkeit und Fehlerverhalten."}];if(typeof module!=="undefined"&&module.exports)module.exports=root.SDAkademieKurse["javascript-aufbau"];})(typeof window!=="undefined"?window:globalThis);
